const C = $('CONFIG').first().json;
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rbad = [];
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
if (!['alert', 'redrive'].includes(C.RECONCILE_ACTION)) rbad.push('CONFIG.RECONCILE_ACTION must be "alert" or "redrive"');
if (!(Number(C.RECONCILE_STALE_SECONDS) > 0)) rbad.push('CONFIG.RECONCILE_STALE_SECONDS must be a number > 0');
else if (Number(C.RECONCILE_STALE_SECONDS) < Number(C.RECLAIM_AFTER_SECONDS)) rbad.push('CONFIG.RECONCILE_STALE_SECONDS must not be smaller than RECLAIM_AFTER_SECONDS (a first delivery may still be running)');
if (!(Number.isInteger(Number(C.RECONCILE_MAX_PER_RUN)) && Number(C.RECONCILE_MAX_PER_RUN) >= 1 && Number(C.RECONCILE_MAX_PER_RUN) <= 200)) rbad.push('CONFIG.RECONCILE_MAX_PER_RUN must be a whole number from 1 to 200');
if (typeof C.RECONCILE_AUTH_TOKEN !== 'string' || C.RECONCILE_AUTH_TOKEN.length < 8) rbad.push('CONFIG.RECONCILE_AUTH_TOKEN must be set (at least 8 characters) when RECONCILE_ENABLED is true');
if (C.RECONCILE_ACTION === 'redrive' && !/^https?:\/\//.test(C.REDRIVE_BASE_URL || '')) rbad.push("CONFIG.REDRIVE_BASE_URL must be this n8n instance's base URL (http:// or https://) when RECONCILE_ACTION is \"redrive\"");
if (!/^https?:\/\//.test(C.EVENTS_STORE_API_URL || '')) rbad.push('CONFIG.EVENTS_STORE_API_URL must start with http:// or https://');
if (C.SLACK_WEBHOOK_URL && !/^https?:\/\//.test(C.SLACK_WEBHOOK_URL)) rbad.push('CONFIG.SLACK_WEBHOOK_URL must be blank or start with http:// or https://');
try { if (!isObj(JSON.parse(C.SERVICE_HEADERS_JSON || '{}'))) throw 0; } catch (e) { rbad.push('CONFIG.SERVICE_HEADERS_JSON must be a JSON object'); }
const inp = $input.first().json;
const via = inp._via;
const stop = (status, error, extra, alert) => [{ json: { run: false, via, http_status: status, response_body: { error, ...(extra || {}) }, alert: alert || null } }];
if (C.RECONCILE_ENABLED !== true) return stop(403, 'reconcile_disabled');
if (rbad.length) return stop(500, 'reconcile_misconfigured', { details: rbad }, via === 'schedule' ? '[Orders] ' + esc('The scheduled reconcile could not run: ' + rbad.join('; ')) : null);
if (via === 'api' && (inp.headers || {})['x-reconcile-token'] !== C.RECONCILE_AUTH_TOKEN) return stop(401, 'unauthorized');
return [{ json: { run: true, via } }];

const C = $('CONFIG').first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const parse = (r) => { const b = r.body && typeof r.body === 'object' ? r.body : null; return r.statusCode === 200 && b && Array.isArray(b.events) ? b.events : null; };
const recv = parse($('List Stale Received').first().json), pend = parse($input.first().json);
const errors = [];
if (recv === null) errors.push('the event store could not list stuck "received" orders');
if (pend === null) errors.push('the event store could not list "pending_manual" orders');
const now = Date.now(), minAge = Number(C.RECONCILE_STALE_SECONDS) * 1000, cap = Number(C.RECONCILE_MAX_PER_RUN);
const idOk = (e) => isObj(e) && typeof e.order_id === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(e.order_id);
// do not trust the store's filtering: keep only what really is stuck for long enough
const stale = (recv || []).filter((e) => idOk(e) && e.status === 'received' && now - Date.parse(e.received_at) >= minAge).slice(0, cap);
const manual = (pend || []).filter((e) => idOk(e) && e.status === 'pending_manual').slice(0, cap).map((e) => ({ order_id: e.order_id, reason: typeof e.reason === 'string' ? e.reason.slice(0, 200) : null }));
const redrive = errors.length === 0 && C.RECONCILE_ACTION === 'redrive' ? stale.map((e) => e.order_id) : [];   // only "received" is ever re-run; pending_manual never
return [{ json: { errors, stale_received: stale.map((e) => e.order_id), pending_manual: manual, action: C.RECONCILE_ACTION, redrive_ids: redrive } }];

const ids = $('Split Redrive').all().map((i) => i.json.order_id);
const res = $input.all().map((i) => i.json);
const out = { started: [], not_claimed: [], failed: [] };
res.forEach((r, k) => {
  const id = ids[k] || '?';
  const b = r.body && typeof r.body === 'object' ? r.body : {};
  if (r.statusCode === 200 && b.status === 'redriving') out.started.push(id);
  else if (r.statusCode === 200 && b.status === 'not_claimed') out.not_claimed.push(id);
  else out.failed.push({ order_id: id, detail: typeof r.statusCode === 'number' ? 'HTTP ' + r.statusCode : 'no response' });
});
return [{ json: out }];

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = $('CONFIG').first().json;
const plan = $('Reconcile Plan').first().json;
if (!plan.run) return [{ json: { http_status: plan.http_status, response_body: plan.response_body, alert: plan.alert } }];
const T = $('Reconcile Triage').first().json;
const R = $('Redrive Results').isExecuted ? $('Redrive Results').first().json : null;
const lines = [];
const mins = Math.round(Number(C.RECONCILE_STALE_SECONDS) / 60 * 10) / 10;
if (T.errors.length) lines.push('Reconcile problem: ' + T.errors.join('; ') + '. Nothing was re-run.');
if (T.action === 'alert' && T.stale_received.length) lines.push(`${T.stale_received.length} order(s) were accepted but never finished (stuck in "received" for over ${mins} min): ${T.stale_received.join(', ')}. Re-drive them or process them by hand.`);
if (R) {
  lines.push(`Reconcile re-ran ${R.started.length} stuck order(s)${R.started.length ? ': ' + R.started.join(', ') : ''}.`);
  if (R.not_claimed.length) lines.push(`Skipped (already finished or taken by someone else): ${R.not_claimed.join(', ')}.`);
  if (R.failed.length) lines.push(`Could not start: ${R.failed.map((f) => f.order_id + ' (' + f.detail + ')').join(', ')}.`);
}
if (T.pending_manual.length) lines.push(`${T.pending_manual.length} order(s) are waiting for a person (pending_manual): ${T.pending_manual.map((m) => m.order_id + (m.reason ? ' [' + m.reason + ']' : '')).join(', ')}.`);
const body = { status: T.errors.length ? 'incomplete' : 'ok', action: T.action, stale_received: T.stale_received, pending_manual: T.pending_manual.map((m) => m.order_id), redriven: R ? R.started : [], skipped: R ? R.not_claimed : [], failed: R ? R.failed : [], problems: T.errors };
return [{ json: { http_status: 200, response_body: body, alert: lines.length ? '[Orders] ' + esc(lines.join(' ')) : null } }];

const C = $('CONFIG').first().json;
const rbad = [];
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
if (!['alert', 'redrive'].includes(C.RECONCILE_ACTION)) rbad.push('CONFIG.RECONCILE_ACTION must be "alert" or "redrive"');
if (!(Number(C.RECONCILE_STALE_SECONDS) > 0)) rbad.push('CONFIG.RECONCILE_STALE_SECONDS must be a number > 0');
else if (Number(C.RECONCILE_STALE_SECONDS) < Number(C.RECLAIM_AFTER_SECONDS)) rbad.push('CONFIG.RECONCILE_STALE_SECONDS must not be smaller than RECLAIM_AFTER_SECONDS (a first delivery may still be running)');
if (!(Number.isInteger(Number(C.RECONCILE_MAX_PER_RUN)) && Number(C.RECONCILE_MAX_PER_RUN) >= 1 && Number(C.RECONCILE_MAX_PER_RUN) <= 200)) rbad.push('CONFIG.RECONCILE_MAX_PER_RUN must be a whole number from 1 to 200');
if (typeof C.RECONCILE_AUTH_TOKEN !== 'string' || C.RECONCILE_AUTH_TOKEN.length < 8) rbad.push('CONFIG.RECONCILE_AUTH_TOKEN must be set (at least 8 characters) when RECONCILE_ENABLED is true');
if (C.RECONCILE_ACTION === 'redrive' && !/^https?:\/\//.test(C.REDRIVE_BASE_URL || '')) rbad.push("CONFIG.REDRIVE_BASE_URL must be this n8n instance's base URL (http:// or https://) when RECONCILE_ACTION is \"redrive\"");
if (!/^https?:\/\//.test(C.EVENTS_STORE_API_URL || '')) rbad.push('CONFIG.EVENTS_STORE_API_URL must start with http:// or https://');
if (C.SLACK_WEBHOOK_URL && !/^https?:\/\//.test(C.SLACK_WEBHOOK_URL)) rbad.push('CONFIG.SLACK_WEBHOOK_URL must be blank or start with http:// or https://');
try { if (!isObj(JSON.parse(C.SERVICE_HEADERS_JSON || '{}'))) throw 0; } catch (e) { rbad.push('CONFIG.SERVICE_HEADERS_JSON must be a JSON object'); }
const inp = $input.first().json;
const stop = (status, error, extra) => [{ json: { go: false, http_status: status, response_body: { error, ...(extra || {}) } } }];
if (C.RECONCILE_ENABLED !== true) return stop(403, 'reconcile_disabled');
if (rbad.length) return stop(500, 'reconcile_misconfigured', { details: rbad });
if ((inp.headers || {})['x-reconcile-token'] !== C.RECONCILE_AUTH_TOKEN) return stop(401, 'unauthorized');
const b = inp.body;
if (!isObj(b) || typeof b.order_id !== 'string' || !/^[A-Za-z0-9._:-]{1,128}$/.test(b.order_id)) return stop(400, 'validation_failed', { details: ['order_id is required (1-128 characters: letters, digits and . _ : -)'] });
return [{ json: { ok: true, order_id: b.order_id } }];

const id = $('Redrive Check').first().json.order_id;
const r = $input.first().json;
const b = r.body && typeof r.body === 'object' ? r.body : {};
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const out = (go, status, body, extra = {}) => [{ json: { go, http_status: status, response_body: body, ...extra } }];
if (r.statusCode === 200 && b.claimed === true) {
  const o = b.record && b.record.order;
  if (isObj(o) && o.order_id === id && Array.isArray(o.line_items)) return out(true, 200, { status: 'redriving', order_id: id }, { order: o, _redrive: true });
  return out(false, 422, { error: 'stored_order_unusable', order_id: id });
}
if (r.statusCode === 409) return out(false, 200, { status: 'not_claimed', order_id: id, state: (b.record && b.record.status) || null });
if (r.statusCode === 404) return out(false, 404, { error: 'unknown_order', order_id: id });
return out(false, 503, { error: 'event_store_unavailable', order_id: id, retry: true });

const M = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
// ---- notices (data): checked, then completed with the defaults the engine insists on
const STATUSES = ['fulfilled', 'backordered', 'pending_manual'];
const nb = [];
const N = M.notices;
if (!isObj(N)) nb.push('notices must be an object');
else {
  for (const k of ['customer_templates', 'ops_alerts']) {
    if (!isObj(N[k])) { nb.push(`notices.${k} must be an object`); continue; }
    for (const [st, v] of Object.entries(N[k])) {
      if (!STATUSES.includes(st)) nb.push(`notices.${k}.${st}: status must be one of ${STATUSES.join(', ')}`);
      else if (k === 'customer_templates' && !(typeof v === 'string' && /^[A-Za-z0-9_.-]{1,64}$/.test(v))) nb.push(`notices.customer_templates.${st} must be a template name (letters, digits, _ . -)`);
      else if (k === 'ops_alerts' && !(typeof v === 'string' && v.trim() !== '' && v.length <= 500)) nb.push(`notices.ops_alerts.${st} must be text of 1 to 500 characters`);
    }
  }
}
let notices = null;
if (!nb.length) {
  notices = { customer_templates: { ...N.customer_templates }, ops_alerts: { ...N.ops_alerts } };
  if (!notices.ops_alerts.pending_manual) notices.ops_alerts.pending_manual = 'Order {order_id} needs manual reconciliation: {reason}';   // an order needing a human ALWAYS reaches ops
}
const o = M.order;
const fallback = { customer_templates: {}, ops_alerts: { pending_manual: 'Order {order_id} needs manual reconciliation: {reason}' } };
return [{ json: { order: o, notices: notices || fallback, extra_alert: notices ? null : `Order ${o.order_id} was re-driven but the Order Mapping notices settings are invalid (${nb.join('; ').slice(0, 300)}); customer notices were skipped.` } }];

if ($('Redrive Go?').isExecuted) { const n = $input.first().json; return [{ json: { order: n.order, notices: n.notices, extra_alert: n.extra_alert, source: 'redrive' } }]; }
const v = $('Validate Order').first().json;
return [{ json: { order: v.order, notices: v.notices, extra_alert: null, source: 'webhook' } }];

const inp = $input.first().json;
const C = $('CONFIG').first().json;
let raw = '';
try { const buf = await this.helpers.getBinaryDataBuffer(0, 'data'); raw = buf.toString('utf8'); } catch (e) { raw = ''; }
const headers = inp.headers || {};
const hv = (name) => String(headers[String(name || '').toLowerCase()] || '').trim();
// How each sender signs. "generic" is configurable (CONFIG); the others are fixed presets.
const SCHEMES = {
  generic: { header: C.SIGNATURE_HEADER, ts_header: C.TIMESTAMP_HEADER, signs: C.SIGNED_CONTENT === 'body' ? 'body' : 'timestamp.body', encoding: C.SIGNATURE_ENCODING === 'base64' ? 'base64' : 'hex', parse: 'plain' },
  stripe: { header: 'stripe-signature', signs: 'timestamp.body', encoding: 'hex', parse: 'stripe' },
  github: { header: 'x-hub-signature-256', signs: 'body', encoding: 'hex', parse: 'sha256-prefix' },
  shopify: { header: 'x-shopify-hmac-sha256', signs: 'body', encoding: 'base64', parse: 'plain' },
};
const scheme = Object.prototype.hasOwnProperty.call(SCHEMES, C.SIGNATURE_SCHEME) ? C.SIGNATURE_SCHEME : 'generic';
const S = SCHEMES[scheme];
const headerValue = hv(S.header);
const norm = (v) => (S.encoding === 'hex' ? v.toLowerCase() : v);
let ts = S.ts_header ? hv(S.ts_header) : '';
let sigs = [];
if (S.parse === 'stripe') {
  for (const part of headerValue.split(',')) {
    const i = part.indexOf('=');
    if (i < 1) continue;
    const k = part.slice(0, i).trim(), v = part.slice(i + 1).trim();
    if (k === 't') ts = v; else if (k === 'v1' && v) sigs.push(norm(v));
  }
} else if (headerValue) {
  let v = headerValue;
  if (S.parse === 'sha256-prefix' && !/^sha256=/i.test(v)) v = '';
  else if (S.encoding === 'hex') v = v.replace(/^sha256=/i, '');
  if (v) sigs = [norm(v)];
}
const needs_ts = S.signs === 'timestamp.body' || !!String(S.ts_header || '').trim();
const sign_base = S.signs === 'timestamp.body' ? `${ts}.${raw}` : raw;
return [{ json: { raw, sign_base, ts, sigs, header_present: !!headerValue, needs_ts, encoding: S.encoding, scheme } }];

const C = $('CONFIG').first().json;
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const bad = [];
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const url = (v) => /^https?:\/\//.test(v || '');
if (typeof C.WEBHOOK_SIGNING_SECRET !== 'string' || C.WEBHOOK_SIGNING_SECRET.length < 8) bad.push('CONFIG.WEBHOOK_SIGNING_SECRET must be set (at least 8 characters; use a long random value)');
if (!['off', 'rejected', 'any'].includes(C.RELEASE_RESERVATION_ON_OMS_FAILURE)) bad.push('CONFIG.RELEASE_RESERVATION_ON_OMS_FAILURE must be off, rejected or any');
if (!['generic', 'stripe', 'github', 'shopify'].includes(C.SIGNATURE_SCHEME)) bad.push('CONFIG.SIGNATURE_SCHEME must be generic, stripe, github or shopify');
if (!['timestamp.body', 'body'].includes(C.SIGNED_CONTENT)) bad.push('CONFIG.SIGNED_CONTENT must be "timestamp.body" or "body"');
if (!['hex', 'base64'].includes(C.SIGNATURE_ENCODING)) bad.push('CONFIG.SIGNATURE_ENCODING must be "hex" or "base64"');
if (C.SIGNATURE_SCHEME === 'generic') {
  if (!/^[A-Za-z0-9-]{1,64}$/.test(C.SIGNATURE_HEADER || '')) bad.push('CONFIG.SIGNATURE_HEADER must be a header name (letters, digits, -)');
  if (C.TIMESTAMP_HEADER ? !/^[A-Za-z0-9-]{1,64}$/.test(C.TIMESTAMP_HEADER) : C.SIGNED_CONTENT !== 'body') bad.push('CONFIG.TIMESTAMP_HEADER must be a header name (letters, digits, -); it can be blank only when SIGNED_CONTENT is "body"');
}
for (const k of ['EVENTS_STORE_API_URL', 'INVENTORY_API_URL', 'OMS_API_URL']) if (!url(C[k])) bad.push(`CONFIG.${k} must start with http:// or https://`);
for (const k of ['NOTIFY_API_URL', 'SECURITY_LOG_API_URL', 'SLACK_WEBHOOK_URL']) if (C[k] && !url(C[k])) bad.push(`CONFIG.${k} must be blank or start with http:// or https://`);
try { if (!isObj(JSON.parse(C.SERVICE_HEADERS_JSON || '{}'))) throw 0; } catch (e) { bad.push('CONFIG.SERVICE_HEADERS_JSON must be a JSON object'); }
for (const k of ['TIMESTAMP_TOLERANCE_SECONDS', 'RECLAIM_AFTER_SECONDS', 'REQUEST_TIMEOUT_MS', 'FULFILMENT_TIMEOUT_MS']) if (!(Number(C[k]) > 0)) bad.push(`CONFIG.${k} must be a number > 0`);
const P = $('Prepare Verification').first().json;
const computed = String($input.first().json.sig_hmac || '');
const stop = (status, error, extra = {}, security = null) => [{ json: { ok: false, http_status: status, response_body: { error, ...extra }, security } }];
if (bad.length) return stop(500, 'webhook_misconfigured', { details: bad });

// ---- signature + timestamp (scheme: generic, stripe, github or shopify). The reply never says WHICH check failed; the reason goes to the security log.
const deny = (reason) => stop(401, 'unauthorized', {}, { reason });
if (!P.header_present) return deny('missing signature header');
if (!P.sigs.length) return deny('signature header is not in the expected format');
if (P.needs_ts) {
  if (!P.ts) return deny('missing timestamp header');
  if (!/^\d{1,13}$/.test(P.ts)) return deny('timestamp is not an integer');
  let tsn = Number(P.ts); if (tsn > 1e12) tsn = tsn / 1000;
  if (Math.abs(Date.now() / 1000 - tsn) > Number(C.TIMESTAMP_TOLERANCE_SECONDS)) return deny(`timestamp outside the ${C.TIMESTAMP_TOLERANCE_SECONDS}s window (possible replay)`);
}
let matched = false;
for (const sig of P.sigs) {                           // Stripe can send several v1 signatures while a secret is being rotated
  if (!computed || computed.length !== sig.length) continue;
  let diff = 0;                                       // constant-time compare: no early exit
  for (let i = 0; i < computed.length; i++) diff |= computed.charCodeAt(i) ^ sig.charCodeAt(i);
  if (diff === 0) matched = true;
}
if (!matched) return deny('signature mismatch');

// ---- the (now trusted) payload
let b;
try { b = JSON.parse(P.raw); } catch (e) { return stop(400, 'malformed_payload', { reason: 'body is not valid JSON' }); }
if (!isObj(b)) return stop(400, 'malformed_payload', { reason: 'body must be a JSON object' });
return [{ json: { ok: true, body: b, raw: P.raw } }];

// ============================================================================
// ORDER MAPPING: the node for sender-specific logic. Edit only between the EDIT lines.
// The signature has ALREADY been verified when this runs. Whatever you write here, the next
// node (Validate Order) checks the result before anything is recorded, reserved or created.
// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
// 1. mapOrder(body): turn the sender's JSON into the standard order.
//    Return { order_id, amount, currency, line_items: [ {..., quantity?} ], customer_email? }
const mapOrder = (body) => ({
  order_id: body.order_id,
  amount: body.amount,
  currency: body.currency,
  line_items: body.line_items,
  customer_email: body.customer_email,
});

// 2. rules: each receives the standard order. Return a sentence to REJECT it (HTTP 422), or nothing.
const rules = [
  // (order) => (order.amount > 5000 ? 'orders over 5000 need manual approval' : null),
];

// 3. notices (plain data). Statuses: fulfilled, backordered, pending_manual.
//    customer_templates: which template name the customer gets for a status (leave a status out = no message)
//    ops_alerts: the Slack text for a status. Use {order_id} {status} {reason} {amount} {currency}.
//    (pending_manual ALWAYS alerts ops: if you remove it, the default text is used.)
const notices = {
  customer_templates: { fulfilled: 'order_confirmation', backordered: 'backorder_notice' },
  ops_alerts: { pending_manual: 'Order {order_id} needs manual reconciliation: {reason}' },
};
// ---- STOP EDITING HERE ------------------------------------------------------
const inp = $input.first().json;
let mapped = null, map_error = null;
const rule_reasons = [];
try { mapped = mapOrder(inp.body); } catch (err) { map_error = String((err && err.message) || err).slice(0, 200); }
if (!map_error && mapped !== null && typeof mapped === 'object' && !Array.isArray(mapped)) {
  for (const r of rules) {
    try { const why = r(mapped); if (why) rule_reasons.push(String(why).slice(0, 300)); }
    catch (err) { rule_reasons.push('custom rule error: ' + String((err && err.message) || err).slice(0, 200)); }
  }
}
return [{ json: { raw: inp.raw, mapped, map_error, rule_reasons, notices, _redrive: inp._redrive === true, order: inp.order } }];

const C = $('CONFIG').first().json;
const M = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const stop = (status, error, extra = {}) => [{ json: { ok: false, http_status: status, response_body: { error, ...extra }, security: null } }];
if (M.error !== undefined) return stop(500, 'order_mapping_failed', { details: [String((M.error && (M.error.message || M.error)) || 'the Order Mapping node could not run').slice(0, 300)] });

// ---- notices (data): checked, then completed with the defaults the engine insists on
const STATUSES = ['fulfilled', 'backordered', 'pending_manual'];
const nb = [];
const N = M.notices;
if (!isObj(N)) nb.push('notices must be an object');
else {
  for (const k of ['customer_templates', 'ops_alerts']) {
    if (!isObj(N[k])) { nb.push(`notices.${k} must be an object`); continue; }
    for (const [st, v] of Object.entries(N[k])) {
      if (!STATUSES.includes(st)) nb.push(`notices.${k}.${st}: status must be one of ${STATUSES.join(', ')}`);
      else if (k === 'customer_templates' && !(typeof v === 'string' && /^[A-Za-z0-9_.-]{1,64}$/.test(v))) nb.push(`notices.customer_templates.${st} must be a template name (letters, digits, _ . -)`);
      else if (k === 'ops_alerts' && !(typeof v === 'string' && v.trim() !== '' && v.length <= 500)) nb.push(`notices.ops_alerts.${st} must be text of 1 to 500 characters`);
    }
  }
}
let notices = null;
if (!nb.length) {
  notices = { customer_templates: { ...N.customer_templates }, ops_alerts: { ...N.ops_alerts } };
  if (!notices.ops_alerts.pending_manual) notices.ops_alerts.pending_manual = 'Order {order_id} needs manual reconciliation: {reason}';   // an order needing a human ALWAYS reaches ops
}

if (nb.length) return stop(500, 'order_playbook_invalid', { details: nb });
// ---- the mapped order
if (M.map_error) return stop(400, 'validation_failed', { details: ['the payload could not be read: ' + M.map_error] });
const b = M.mapped;
if (!isObj(b)) return stop(400, 'validation_failed', { details: ['the order mapping did not return an object'] });
const errors = [];
if (typeof b.order_id !== 'string' || !/^[A-Za-z0-9._:-]{1,128}$/.test(b.order_id)) errors.push('order_id must be 1-128 characters: letters, digits and . _ : -');
if (typeof b.amount !== 'number' || !isFinite(b.amount) || b.amount < 0) errors.push('amount must be a number >= 0');
if (typeof b.currency !== 'string' || !/^[A-Za-z]{3}$/.test(b.currency)) errors.push('currency must be a 3-letter code');
if (!Array.isArray(b.line_items) || b.line_items.length < 1 || b.line_items.length > 200) errors.push('line_items must be an array of 1-200 items');
else b.line_items.forEach((l, i) => {
  if (!isObj(l)) errors.push(`line_items[${i}] must be an object`);
  else if (l.quantity !== undefined && (!Number.isInteger(l.quantity) || l.quantity < 1 || l.quantity > 100000)) errors.push(`line_items[${i}].quantity must be a whole number >= 1`);
});
if (b.customer_email !== undefined && b.customer_email !== null && (typeof b.customer_email !== 'string' || !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(b.customer_email.trim()))) errors.push('customer_email must be a valid email address');
if (errors.length) return stop(400, 'validation_failed', { details: errors });
const order = { order_id: b.order_id, amount: b.amount, currency: b.currency.toUpperCase(), line_items: b.line_items, customer_email: b.customer_email ? b.customer_email.trim().toLowerCase() : null };
if (M.rule_reasons.length) return stop(422, 'order_rejected', { details: M.rule_reasons });
return [{ json: { ok: true, order, raw: M.raw, notices } }];

const C = $('CONFIG').first().json;
const o = $('Validate Order').first().json.order;
const hash = $('Payload Hash').first().json.payload_hash;
const r = $input.first().json;
const b = r.body && typeof r.body === 'object' ? r.body : null;
const stop = (status, body) => [{ json: { ok: false, http_status: status, response_body: body } }];
if (!b || !b.record || (r.statusCode !== 200 && r.statusCode !== 201)) return stop(503, { error: 'event_store_unavailable', order_id: o.order_id, retry: true });
if (r.statusCode === 201) return [{ json: { ok: true, reclaim: false } }];
const rec = b.record;
if (rec.payload_hash !== hash) return stop(409, { error: 'order_conflict', order_id: o.order_id, reason: 'this order_id was already received with different contents' });
const age = (Date.now() - Date.parse(rec.received_at)) / 1000;
if (rec.status === 'received' && age >= Number(C.RECLAIM_AFTER_SECONDS)) return [{ json: { ok: true, reclaim: true } }];
return stop(200, { status: 'duplicate', order_id: o.order_id, state: rec.status });

const o = $('Validate Order').first().json.order;
const r = $input.first().json;
const b = r.body && typeof r.body === 'object' ? r.body : {};
if (r.statusCode === 200 && b.claimed === true) return [{ json: { ok: true } }];
if (r.statusCode === 409) return [{ json: { ok: false, http_status: 200, response_body: { status: 'duplicate', order_id: o.order_id, state: (b.record && b.record.status) || 'received' } } }];
return [{ json: { ok: false, http_status: 503, response_body: { error: 'event_store_unavailable', order_id: o.order_id, retry: true } } }];

const r = $input.first().json;
const ok = typeof r.statusCode === 'number' && r.statusCode >= 200 && r.statusCode < 300;
if (ok) return [{ json: { reserved: true } }];
if (r.statusCode === 409) return [{ json: { reserved: false, outcome: { status: 'backordered', reason: 'insufficient inventory' } } }];
const why = typeof r.statusCode === 'number' ? 'HTTP ' + r.statusCode : 'no response';
return [{ json: { reserved: false, outcome: { status: 'pending_manual', reason: `inventory_unavailable (${why})` } } }];

const C = $('CONFIG').first().json;
const r = $input.first().json;
const ok = typeof r.statusCode === 'number' && r.statusCode >= 200 && r.statusCode < 300;
if (ok) return [{ json: { outcome: { status: 'fulfilled', reason: null }, release: false } }];
const why = typeof r.statusCode === 'number' ? 'HTTP ' + r.statusCode : 'no response';
// A DEFINITE rejection (4xx other than 408/429) means the order system did not create the order. Anything else (no answer, 5xx, 408, 429) may have created it.
const definite = typeof r.statusCode === 'number' && r.statusCode >= 400 && r.statusCode < 500 && r.statusCode !== 408 && r.statusCode !== 429;
const mode = C.RELEASE_RESERVATION_ON_OMS_FAILURE;
const release = mode === 'any' || (mode === 'rejected' && definite);
return [{ json: { outcome: { status: 'pending_manual', reason: `oms_create_failed (${why}); ` + (release ? 'releasing the inventory reservation' : 'inventory is still reserved') }, release, why } }];

const v = $('OMS Verdict').first().json;
const r = $input.first().json;
const ok = typeof r.statusCode === 'number' && ((r.statusCode >= 200 && r.statusCode < 300) || r.statusCode === 404);
const why = typeof r.statusCode === 'number' ? 'HTTP ' + r.statusCode : 'no response';
const base = `oms_create_failed (${v.why})`;
return [{ json: { outcome: { status: 'pending_manual', reason: ok ? base + '; inventory reservation released' : base + `; the inventory reservation could NOT be released (${why}) and is still held`, release: ok ? 'released' : 'failed' } } }];

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const F = $('Order In Flight').first().json;
const o = F.order;
const N = F.notices;
const out = $('Outcome').first().json.outcome;
const r = $input.first().json;
const n = [];
const statusSaved = typeof r.statusCode === 'number' && r.statusCode >= 200 && r.statusCode < 300;
const vals = { order_id: o.order_id, status: out.status, reason: out.reason || 'none', amount: o.amount, currency: o.currency };
const fill = (t) => t.replace(/\{(order_id|status|reason|amount|currency)\}/g, (m, k) => String(vals[k]));   // one pass
const tpl = N.customer_templates[out.status];
if (tpl && o.customer_email) n.push({ kind: 'customer', to: o.customer_email, template: tpl, order_id: o.order_id });
const ops = N.ops_alerts[out.status];
if (ops) n.push({ kind: 'slack', text: fill(ops) });
if (F.extra_alert) n.push({ kind: 'slack', text: F.extra_alert });
if (out.release === 'failed') n.push({ kind: 'slack', text: `Order ${o.order_id}: the inventory reservation could NOT be released after the order system failed. The stock stays held until someone releases it.` });
if (!statusSaved) n.push({ kind: 'slack', text: `Order ${o.order_id}: final status "${out.status}" could not be written to the event store. The event may still show "received". Reason: ${out.reason || 'none'}` });
return [{ json: { notifications: n } }];

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = $('CONFIG').first().json;
const out = [];
for (const n of $input.first().json.notifications || []) {
  if (n.kind === 'slack' && C.SLACK_WEBHOOK_URL) out.push({ json: { kind: 'slack', text: '[Orders] ' + esc(n.text) } });
  if (n.kind === 'customer' && C.NOTIFY_API_URL && n.to) out.push({ json: n });
}
return out;
